-- Open Vanilla: achievements (PENDING: install on launch day with realm/mangos/pending/0002-openvanilla-achievements.patch).
-- GENERATED by tools/gen_achievements.py from realm/achievements/achievements.yml; do not edit.
-- Run against the world database (classicmangos); the per-character tables are created in
-- classiccharacters by name. Idempotent: tables are created if missing and the catalogue is replaced.
-- Achievements give points and recognition only, never power.

-- -- characters -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS classiccharacters.character_achievement (
  guid         INT UNSIGNED NOT NULL COMMENT 'characters.guid',
  achievement  INT UNSIGNED NOT NULL COMMENT 'openvanilla_achievement.id',
  date         INT UNSIGNED NOT NULL COMMENT 'unix time it was earned',
  PRIMARY KEY (guid, achievement)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: earned achievements';

CREATE TABLE IF NOT EXISTS classiccharacters.character_achievement_progress (
  guid         INT UNSIGNED NOT NULL COMMENT 'characters.guid',
  criteria     INT UNSIGNED NOT NULL COMMENT 'openvanilla_achievement_criteria.id (achievement*100+n); 0 = retroactive grant done',
  counter      INT UNSIGNED NOT NULL DEFAULT 0,
  date         INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'unix time of the last change',
  PRIMARY KEY (guid, criteria)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: achievement counters (kills, wins, honorable kills)';

CREATE TABLE IF NOT EXISTS classiccharacters.openvanilla_realm_first (
  achievement  INT UNSIGNED NOT NULL PRIMARY KEY,
  guid         INT UNSIGNED NOT NULL,
  name         VARCHAR(12)  NOT NULL,
  date         INT UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: realm firsts, stored once';

-- -- world: settings and catalogue ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS openvanilla_achievement_config (
  name   VARCHAR(32)  NOT NULL PRIMARY KEY,
  value  INT UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: achievement settings';
-- release_date: what is already done when a character first logs in after launch is granted
-- retroactively, dated this day. Installing this file on launch day sets it to that day.

CREATE TABLE IF NOT EXISTS openvanilla_achievement (
  id           INT UNSIGNED NOT NULL PRIMARY KEY,
  name         VARCHAR(80)  NOT NULL,
  description  VARCHAR(255) NOT NULL,
  points       TINYINT UNSIGNED NOT NULL,
  category     VARCHAR(16)  NOT NULL,
  icon         VARCHAR(80)  NOT NULL,
  faction      TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 both, 1 Alliance, 2 Horde',
  class_mask   INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 every class, else 1<<(class-1)',
  need         TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'criteria needed; 0 = all',
  flags        INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 realm first, 2 group first, 4 feat of strength'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: achievement catalogue';

CREATE TABLE IF NOT EXISTS openvanilla_achievement_criteria (
  id           INT UNSIGNED NOT NULL COMMENT 'achievement*100+n: one requirement',
  alt          TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'alternatives of one requirement (any one counts)',
  achievement  INT UNSIGNED NOT NULL,
  type         TINYINT UNSIGNED NOT NULL COMMENT 'see realm/achievements/PROTOCOL.md',
  value1       INT UNSIGNED NOT NULL DEFAULT 0,
  value2       INT UNSIGNED NOT NULL DEFAULT 0,
  value3       INT UNSIGNED NOT NULL DEFAULT 0,
  count        INT UNSIGNED NOT NULL DEFAULT 0,
  label        VARCHAR(80)  NOT NULL DEFAULT '',
  PRIMARY KEY (id, alt),
  KEY achievement (achievement)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Open Vanilla: achievement criteria';

DELETE FROM openvanilla_achievement_criteria;
DELETE FROM openvanilla_achievement;



